3	import (
4		"fmt"
5		"os"
6		"strings"
7	
8		"github.com/prestontallen/ai-devboard/worklog/internal/devboard"
9		"github.com/prestontallen/ai-devboard/worklog/internal/migrate"
10		"github.com/prestontallen/ai-devboard/worklog/internal/model"
11		"github.com/prestontallen/ai-devboard/worklog/internal/projection"
12		"github.com/prestontallen/ai-devboard/worklog/internal/reindex"
13		"github.com/prestontallen/ai-devboard/worklog/internal/store"
14		"github.com/prestontallen/ai-devboard/worklog/internal/store/sqlitestore"
15	)
16	
17	// nextRank is the Rank a newly created ticket must carry: one past the
18	// highest rank among live tickets, so it renders at the END of its
19	// section.
20	//
21	// Leaving it at the zero value is not "unranked" — it is the literal
22	// rank of whichever ticket sits first in WORK.md, because convert
23	// numbers document position from zero (convert/workmd.go:73). A new
24	// ticket defaulting to 0 therefore *ties* the first ticket, and
25	// Tickets() breaks that tie with `ORDER BY rank, slug` — so the new
26	// ticket silently sorts by alphabetical luck instead of landing where
27	// the human put it. Observed live: a ticket added on 2026-09-03 tied
28	// adb-research-mode at rank 0 and won the slug comparison, jumping to
29	// the top of ## Now.
30	//
31	// Archived tickets are excluded: their Rank is a position within an
32	// archive month, a different numbering space that says nothing about
33	// where a live ticket belongs.
34	func nextRank(s store.Store) (int, error) {
35		tickets, err := s.Tickets()
36		if err != nil {
37			return 0, err
38		}
39		max := -1
40		for _, t := range tickets {
41			if !t.Archived && t.Rank > max {
42				max = t.Rank
43			}
44		}
45		return max + 1, nil
46	}
47	
48	// nextRosterRank is nextRank for an epic's child roster. Same collision,
49	// one level down: RosterRank is assigned only by convert (convert.go:161,
50	// :181), so a child added through the CLI defaults to 0, ties the epic's
51	// first child, and is ordered against it by slug.
52	func nextRosterRank(s store.Store, parent store.ID) (int, error) {
53		kids, err := s.Children(parent)
54		if err != nil {
55			return 0, err
56		}
57		return nextRosterRankOf(kids), nil
58	}
59	
60	// nextRosterRankOf is nextRosterRank for a caller that already holds the
61	// roster, so the only copy of the "one past the highest" rule lives here.
62	func nextRosterRankOf(kids []*store.Ticket) int {
63		max := -1
64		for _, k := range kids {
65			if k.RosterRank > max {
66				max = k.RosterRank
67			}
68		}
69		return max + 1
70	}
71	
72	// requireAdopted refuses before opening a store that does not exist yet.
73	//
74	// Without this the machine gets the wrong error entirely: sqlitestore.Open
75	// CREATES the database when the path is absent, so the verb proceeds
76	// against an empty store, Render emits a WORK.md the corpus does not
77	// match, and EditedIn reports every file as "edited by hand" — on a
78	// machine where nobody edited anything. Worse, the advice that refusal
79	// gives ("they are build outputs; the store is the source") is actively
80	// dangerous against an empty store: following it means deleting the
81	// corpus. Say what is actually true instead, and name the command.
82	func requireAdopted(dataDir string) error {
83		if _, err := os.Stat(migrate.OutputPath(dataDir)); err == nil {
84			return nil
85		} else if !os.IsNotExist(err) {
86			return fmt.Errorf("opening store: %w", err)
87		}
88		return errWithExit(1,
89			"this machine has not adopted the store yet — no database at %s\nrun `worklog adopt` to preview the adoption, then `worklog adopt --commit`",
90			migrate.OutputPath(dataDir))
91	}
92	
93	// storeSession is one write verb's open store handle plus the layout it
94	// renders into — the shared plumbing every ticket-shaped store-backed
95	// write verb (start/done/edit/pr/link/note/wait/add/import) opens once,
96	// mutates a *store.Ticket (or several) against, and commits. The
97	// task<sub> family (task_store.go) predates this helper and keeps its
98	// own inline version; not worth touching already-shipped, tested code
99	// to unify the ~15 lines of overlap.
100	type storeSession struct {
101		s      store.Store
102		layout projection.Layout
103		wd     model.Workdir
104	}
105	
106	// openStoreForWrite opens the store and refuses up front if any
107	// projection under wd/devboard has been hand-edited since the last
108	// render — the M3b policy: refuse before mutating, never after, since a
109	// render destroys whatever a human typed by hand.
110	func openStoreForWrite(wd model.Workdir) (*storeSession, error) {
111		dataDir, err := storeDataDir()
112		if err != nil {
113			return nil, err
114		}
115		if err := requireAdopted(dataDir); err != nil {
116			return nil, err
117		}
118		s, err := sqlitestore.Open(migrate.OutputPath(dataDir))
119		if err != nil {
120			return nil, fmt.Errorf("opening store: %w", err)
121		}
122		layout := projection.Layout{WorklogDir: wd.Root, DevboardDir: devboard.DataDir()}
123	
124		edited, err := projection.EditedIn(s, layout)
125		if err != nil {
126			s.Close()
127			return nil, fmt.Errorf("checking projections: %w", err)
128		}
129		if len(edited) > 0 {
130			s.Close()
131			return nil, errWithExit(1,
132				"refusing to write — these projections were edited by hand and a re-render would discard the changes:\n  %s\nreconcile them first (they are build outputs; the store is the source)",
133				strings.Join(edited, "\n  "))
134		}
135		return &storeSession{s: s, layout: layout, wd: wd}, nil
136	}
137	
138	func (ss *storeSession) close() { ss.s.Close() }
139	
140	// commit persists t and synchronously re-renders every projection plus
141	// INDEX.md, so the dashboard and session-start hook see the write before
142	// this process exits (contract criterion 3). Unlike the task<sub> family,
143	// which never touches an indexed field, these verbs can change
144	// title/section/repo/tags, so INDEX.md is regenerated every time.
145	func (ss *storeSession) commit(t *store.Ticket) error {
146		if err := ss.s.PutTicket(t); err != nil {
147			return err
148		}
149		return ss.render()
150	}
151	
152	// commitFeedback persists e and re-renders — FEEDBACK.md isn't one of
153	// INDEX.md's four sections (ticket/tag/repo/archive-month), so no
154	// reindex is needed here.
155	func (ss *storeSession) commitFeedback(e *store.FeedbackEntry) error {
156		if err := ss.s.PutFeedback(e); err != nil {
157			return err
158		}
159		return projection.RenderTo(ss.s, ss.layout)
160	}
161	
162	func (ss *storeSession) render() error {
163		if err := projection.RenderTo(ss.s, ss.layout); err != nil {
164			return fmt.Errorf("rendering projections: %w", err)
165		}
166		if _, err := reindex.Run(ss.wd, reindex.Inputs{}); err != nil {
167			return fmt.Errorf("regenerating INDEX.md: %w", err)
168		}
169		return nil
170	}
171	
172	// ensureBoardTracked replicates the one create-if-missing devboard hook
173	// the legacy write surface had (devboard.OnStart — done/pr/link's hooks
174	// all no-op on a missing entry, matching devboard.Find's contract). A
175	// ticket that has never been on the board gets BoardTracked, its session
176	// (for the dashboard's resume button — dev-context documents this as
177	// automatic on start), branch, and repo path; an already-tracked ticket
178	// only gets its repo path self-healed, same as legacy. declaredRepo is
179	// the ticket's own canonical Repo, used only to resolve a filesystem
180	// root when RepoPath is empty or has gone away.
181	func ensureBoardTracked(t *store.Ticket, declaredRepo string) {
182		if t.BoardTracked {
183			if t.RepoPath == "" || !dirExists(t.RepoPath) {
184				if root := devboard.RepoRootFor(declaredRepo); root != "" {
185					t.RepoPath = root
186				}
187			}
188			return
189		}
190		if !devboard.Enabled() {
191			return // devboard is opt-in by dir presence; a first tracking is a no-op, not a create
192		}
193		t.BoardTracked = true
194		if s := os.Getenv("CLAUDE_CODE_SESSION_ID"); s != "" {
195			t.Session = s
196		}
197		if b := devboard.GitBranch(); b != "" {
198			t.Branch = b
199		}
200		if root := devboard.RepoRootFor(declaredRepo); root != "" {
201			t.RepoPath = root
202		}
203	}
204	
205	// ensureParentBoardTracked replicates legacy's devboardSyncEpic, called on
206	// every child start/resume/done: a child's parent epic never goes through
207	// its own start (epics can't occupy ## Now), so nothing else ever
208	// board-tracks it. Without this, an epic's own file is never created and
209	// children with nowhere to nest never render. No-ops for a standalone
210	// ticket (t.ParentID == "") or if the parent lookup fails — a dangling
211	// ParentID is reported by the caller's own checks, not silently patched
212	// here.
213	func ensureParentBoardTracked(ss *storeSession, t *store.Ticket) error {
214		if t.ParentID == "" {
215			return nil
216		}
217		parent, err := ss.s.Ticket(t.ParentID)
218		if err != nil {
219			return nil
220		}
221		ensureBoardTracked(parent, parent.Repo)
222		return ss.s.PutTicket(parent)
223	}
224	
225	// clearBoardTracked is untrack's store-side half. Render only ever writes
226	// the files it expects (every BoardTracked, non-child ticket); it never
227	// prunes a file that fell out of that set, so deleting a task file alone
228	// would leave it recreated on the next write that happens to re-render.
229	// No-op (not an error) when id doesn't resolve to a store ticket — a bare
230	// producer file (no worklog: join key) has nothing in the store to clear,
231	// and the caller deletes the file directly in that case.
232	func clearBoardTracked(wd model.Workdir, id string) error {
233		ss, err := openStoreForWrite(wd)
234		if err != nil {
235			return err
236		}
237		defer ss.close()
238		t, err := ss.s.TicketBySlug(id)
239		if store.IsNotFound(err) {
240			return nil
241		}
242		if err != nil {
243			return err
244		}
245		t.BoardTracked = false
246		return ss.commit(t)
247	}
248	
249	func dirExists(p string) bool {
250		if p == "" {
251			return false
252		}
253		fi, err := os.Stat(p)
254		return err == nil && fi.IsDir()
255	}
256	
257	// ticketBySlugOrErr resolves slug to a *store.Ticket, mapping a
258	// not-found lookup to notFoundErr (typically a package's own
259	// ErrIDNotFound sentinel) so callers keep their existing error-mapping
260	// switch statements unchanged between the legacy and store paths.
261	func (ss *storeSession) ticketBySlugOrErr(slug string, notFoundErr error) (*store.Ticket, error) {
262		t, err := ss.s.TicketBySlug(slug)
263		if store.IsNotFound(err) {
264			return nil, fmt.Errorf("%w: %q", notFoundErr, slug)
265		}
266		if err != nil {
267			return nil, err
268		}
269		return t, nil
270	}
